import{_ as o,o as e,c as a,ag as r}from"./chunks/framework.DXGyWiRo.js";const p=JSON.parse('{"title":"Политика Cookie и аналитических технологий","description":"","frontmatter":{},"headers":[],"relativePath":"cookie-policy.md","filePath":"cookie-policy.md","lastUpdated":null}'),d={name:"cookie-policy.md"};function i(l,t,s,h,n,c){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="политика-cookie-и-аналитических-технологии" tabindex="-1">Политика Cookie и аналитических технологий <a class="header-anchor" href="#политика-cookie-и-аналитических-технологии" aria-label="Permalink to &quot;Политика Cookie и аналитических технологий&quot;">​</a></h1><p><strong>ИП Ульянов Алексей Владимирович</strong><br> ОГРНИП 321132600016985<br> Email: <a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a></p><p><em>Редакция от 21 апреля 2026 г.</em></p><hr><p>Настоящая Политика описывает, как сайт <a href="https://gosms.ru" target="_blank" rel="noreferrer">gosms.ru</a> и связанные с ним сервисы используют файлы cookie, Local Storage и аналогичные технологии (далее совместно — <strong>Cookie</strong>).</p><h2 id="_1-что-такое-cookie" tabindex="-1">1. Что такое Cookie <a class="header-anchor" href="#_1-что-такое-cookie" aria-label="Permalink to &quot;1. Что такое Cookie&quot;">​</a></h2><p>Cookie — небольшой текстовый файл, который сайт сохраняет в браузере пользователя при посещении. Cookie позволяют сайту запоминать настройки, данные авторизации и отслеживать информацию об использовании ресурса.</p><p><strong>Local Storage</strong> — аналогичный механизм хранения данных в браузере без ограничений по сроку действия, не передаётся на сервер автоматически.</p><h2 id="_2-какие-cookie-мы-используем" tabindex="-1">2. Какие Cookie мы используем <a class="header-anchor" href="#_2-какие-cookie-мы-используем" aria-label="Permalink to &quot;2. Какие Cookie мы используем&quot;">​</a></h2><h3 id="_2-1-обязательные-технические-cookie" tabindex="-1">2.1. Обязательные (технические) Cookie <a class="header-anchor" href="#_2-1-обязательные-технические-cookie" aria-label="Permalink to &quot;2.1. Обязательные (технические) Cookie&quot;">​</a></h3><p>Необходимы для корректной работы сайта. Без них невозможна авторизация и использование личного кабинета. Устанавливаются автоматически при посещении сайта; <strong>согласие не требуется</strong>.</p><table tabindex="0"><thead><tr><th>Название</th><th>Назначение</th><th>Срок действия</th></tr></thead><tbody><tr><td><code>session_id</code></td><td>Идентификатор сессии авторизации</td><td>До закрытия браузера / 30 дней</td></tr><tr><td><code>access_token</code></td><td>JWT-токен доступа</td><td>15 минут</td></tr><tr><td><code>refresh_token</code></td><td>Токен обновления сессии</td><td>7 дней</td></tr><tr><td><code>csrf_token</code></td><td>Защита от CSRF-атак</td><td>Сессия</td></tr><tr><td><code>theme</code></td><td>Настройка темы оформления (светлая/тёмная)</td><td>1 год</td></tr><tr><td><code>lang</code></td><td>Язык интерфейса</td><td>1 год</td></tr></tbody></table><h3 id="_2-2-аналитические-cookie" tabindex="-1">2.2. Аналитические Cookie <a class="header-anchor" href="#_2-2-аналитические-cookie" aria-label="Permalink to &quot;2.2. Аналитические Cookie&quot;">​</a></h3><p>Используются для понимания того, как посетители взаимодействуют с сайтом. Данные анализируются в агрегированном (обезличенном) виде.</p><table tabindex="0"><thead><tr><th>Сервис</th><th>Назначение</th><th>Срок действия</th><th>Политика конфиденциальности</th></tr></thead><tbody><tr><td>Яндекс.Метрика</td><td>Анализ посещаемости и поведения пользователей</td><td>До 1 года</td><td><a href="https://yandex.ru/legal/metrica_termsofuse" target="_blank" rel="noreferrer">yandex.ru/legal/metrica_termsofuse</a></td></tr></tbody></table><h3 id="_2-3-функциональные-cookie-local-storage" tabindex="-1">2.3. Функциональные Cookie / Local Storage <a class="header-anchor" href="#_2-3-функциональные-cookie-local-storage" aria-label="Permalink to &quot;2.3. Функциональные Cookie / Local Storage&quot;">​</a></h3><p>Обеспечивают дополнительные функции и персонализацию.</p><table tabindex="0"><thead><tr><th>Название</th><th>Назначение</th><th>Тип хранилища</th><th>Срок действия</th></tr></thead><tbody><tr><td><code>ui_preferences</code></td><td>Настройки интерфейса (ширина колонок, сортировка)</td><td>Local Storage</td><td>Бессрочно (до очистки)</td></tr><tr><td><code>dashboard_layout</code></td><td>Расположение виджетов на главной</td><td>Local Storage</td><td>Бессрочно (до очистки)</td></tr><tr><td><code>notifications_read</code></td><td>Список прочитанных уведомлений</td><td>Local Storage</td><td>30 дней</td></tr></tbody></table><h2 id="_3-сторонние-сервисы" tabindex="-1">3. Сторонние сервисы <a class="header-anchor" href="#_3-сторонние-сервисы" aria-label="Permalink to &quot;3. Сторонние сервисы&quot;">​</a></h2><p>При использовании сайта gosms.ru могут загружаться ресурсы от следующих третьих сторон:</p><table tabindex="0"><thead><tr><th>Сервис</th><th>Назначение</th></tr></thead><tbody><tr><td><strong>Яндекс.Метрика</strong></td><td>Веб-аналитика</td></tr></tbody></table><p>Использование Cookie этими сервисами регулируется их собственными политиками конфиденциальности, ссылки на которые приведены в таблице выше.</p><h2 id="_4-как-управлять-cookie" tabindex="-1">4. Как управлять Cookie <a class="header-anchor" href="#_4-как-управлять-cookie" aria-label="Permalink to &quot;4. Как управлять Cookie&quot;">​</a></h2><h3 id="_4-1-настроики-браузера" tabindex="-1">4.1. Настройки браузера <a class="header-anchor" href="#_4-1-настроики-браузера" aria-label="Permalink to &quot;4.1. Настройки браузера&quot;">​</a></h3><p>Вы можете управлять Cookie через настройки браузера:</p><ul><li><strong>Google Chrome:</strong> Настройки → Конфиденциальность и безопасность → Файлы cookie</li><li><strong>Mozilla Firefox:</strong> Настройки → Приватность и защита</li><li><strong>Safari:</strong> Настройки → Конфиденциальность</li><li><strong>Microsoft Edge:</strong> Настройки → Файлы cookie и разрешения для сайтов</li></ul><div class="warning custom-block"><p class="custom-block-title">Важно</p><p>Блокировка обязательных Cookie приведёт к невозможности авторизации и использования личного кабинета.</p></div><h3 id="_4-2-отказ-от-аналитических-cookie" tabindex="-1">4.2. Отказ от аналитических Cookie <a class="header-anchor" href="#_4-2-отказ-от-аналитических-cookie" aria-label="Permalink to &quot;4.2. Отказ от аналитических Cookie&quot;">​</a></h3><p>Вы можете отключить аналитику:</p><ul><li><strong>Яндекс.Метрика:</strong> Установите <a href="https://yandex.ru/support/metrika/general/opt-out.html" target="_blank" rel="noreferrer">браузерное дополнение</a>.</li><li>Для отключения аналитики на уровне сайта — обратитесь на <a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a>.</li></ul><h2 id="_5-правовое-основание" tabindex="-1">5. Правовое основание <a class="header-anchor" href="#_5-правовое-основание" aria-label="Permalink to &quot;5. Правовое основание&quot;">​</a></h2><p>5.1. Обязательные Cookie устанавливаются на основании <strong>законного интереса</strong> (ст. 6 ч. 1 п. 6 ФЗ-152) — обеспечение безопасной аутентификации.</p><p>5.2. Аналитические и функциональные Cookie устанавливаются на основании <strong>согласия</strong> (ст. 6 ч. 1 п. 1 ФЗ-152), предоставляемого через баннер/настройки при первом посещении сайта.</p><h2 id="_6-изменение-политики" tabindex="-1">6. Изменение Политики <a class="header-anchor" href="#_6-изменение-политики" aria-label="Permalink to &quot;6. Изменение Политики&quot;">​</a></h2><p>Оператор вправе обновлять настоящую Политику. Актуальная версия всегда доступна на <a href="https://legal.gosms.ru/cookie-policy" target="_blank" rel="noreferrer">legal.gosms.ru/cookie-policy</a>.</p><h2 id="_7-контактная-информация" tabindex="-1">7. Контактная информация <a class="header-anchor" href="#_7-контактная-информация" aria-label="Permalink to &quot;7. Контактная информация&quot;">​</a></h2><p><strong>Email:</strong> <a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a></p>',37)])])}const g=o(d,[["render",i]]);export{p as __pageData,g as default};
